package blockbranch.realistic;
import java.nio.file.*;import java.util.*;
/** One matched, fixed three-site admission sequence; no global search or gameplay edits. */
public final class NativeOrdinaryAdmissionProbe {
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STARTED.register(server->{try{if(Boolean.getBoolean("blockbranch.admissionPreparationChecks")){AdmissionPreparationChecks.run(server);return;}var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();AdmissionWorkTrace.seed(level.getChunkSource().randomState().seed());var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();var os=(com.sun.management.OperatingSystemMXBean)java.lang.management.ManagementFactory.getOperatingSystemMXBean();var rows=new ArrayList<Object>();try(var recording=new jdk.jfr.Recording()){recording.enable("jdk.ExecutionSample").withPeriod(java.time.Duration.ofMillis(5));recording.enable("jdk.GarbageCollection");recording.enable("jdk.Compilation").withThreshold(java.time.Duration.ofMillis(1)).withoutStackTrace();recording.enable("jdk.JavaMonitorEnter").withThreshold(java.time.Duration.ofMillis(10));recording.enable("jdk.ThreadPark").withThreshold(java.time.Duration.ofMillis(10));recording.enable("jdk.GCPhasePause");recording.enable("jdk.ExecuteVMOperation").withThreshold(java.time.Duration.ofMillis(1));recording.start();for(var site:NativeOrdinaryQualification.SITES.subList(0,3)){AdmissionWorkTrace.phase(rows.size()+1);var quotaBefore=AdmissionWorkTrace.quota();var interval=new AdmissionWorkTrace.Interval();interval.phase=rows.size()+1;interval.begin();long cpu=os.getProcessCpuTime(),bytes=bean.getTotalThreadAllocatedBytes(),begin=System.nanoTime();var box=new net.minecraft.world.level.levelgen.structure.BoundingBox(site.x()-3,site.y()-3,site.z()-3,site.x()+3,site.y()+5,site.z()+3);if(site.kind()!=null){var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(site.kind());var c=level.getChunk(site.x()>>4,site.z()>>4,net.minecraft.world.level.chunk.status.ChunkStatus.STRUCTURE_STARTS);var st=level.structureManager().getStartForStructure(holder.value(),c);NativeOrdinaryQualification.require(st!=null&&st.isValid(),"Matched actual start");box=st.getBoundingBox();}var actualBox=box;int hx=site.name().equals("shipwreck")?15:6,hz=site.name().equals("shipwreck")?4:6;box=new net.minecraft.world.level.levelgen.structure.BoundingBox(site.x()-hx,site.y()-16,site.z()-hz,site.x()+hx,site.y()+32,site.z()+hz);NativeOrdinaryQualification.require(actualBox.minX()>=box.minX()&&actualBox.maxX()<=box.maxX()&&actualBox.minZ()>=box.minZ()&&actualBox.maxZ()<=box.maxZ(),"Matched chunk coverage contains both bodies");int chunks=0;for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)for(int x=box.minX()>>4;x<=box.maxX()>>4;x++){level.getChunk(x,z);chunks++;}rows.add(Map.of("name",site.name(),"nativeOrdinary",g.nativeOrdinaryDefinition(),"chunks",chunks,"nanos",System.nanoTime()-begin,"processCpuNanos",os.getProcessCpuTime()-cpu,"processAllocatedBytes",bean.getTotalThreadAllocatedBytes()-bytes,"bounds",box.toString()));interval.end();interval.commit();AdmissionWorkTrace.interval(quotaBefore,AdmissionWorkTrace.quota());blockbranch.Blockbranch.LOGGER.info("NATIVE_ORDINARY_ADMISSION {}",rows.getLast());}AdmissionWorkTrace.phase(4);if(g.nativeOrdinaryDefinition()>0&&!Boolean.getBoolean("blockbranch.admissionWorkTrace")&&!Boolean.getBoolean("blockbranch.admissionFixedWork")){var p=g.waygates(level.getChunkSource().randomState()).plans().stream().filter(v->v.y()>1000).findFirst().orElseThrow();var h=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(net.minecraft.world.level.levelgen.structure.BuiltinStructures.RUINED_PORTAL_DESERT);var c=level.getChunk(p.x()>>4,p.z()>>4,net.minecraft.world.level.chunk.status.ChunkStatus.STRUCTURE_STARTS);var st=level.structureManager().getStartForStructure(h.value(),c);NativeOrdinaryQualification.require(st!=null&&st.isValid()&&st.getBoundingBox().minY()>p.y()-32&&st.getBoundingBox().maxY()<p.y()+32&&st.getPieces().getFirst() instanceof net.minecraft.world.level.levelgen.structure.structures.RuinedPortalPiece,"Actual production native high-Y portal start");NativeOrdinaryQualification.write("high-portal-start.json",Map.of("plan",p,"piece",st.getPieces().getFirst().createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level)).toString(),"scope","Actual STRUCTURE_STARTS at high Y; full native function separately checked at selected low-Y portal"));}recording.stop();recording.dump(Path.of("admission.jfr"));}NativeOrdinaryQualification.write("admission.json",rows);if(AdmissionWorkTrace.ON)NativeOrdinaryQualification.write("work-counts.json",AdmissionWorkTrace.snapshot());if(AdmissionWorkTrace.ON)NativeOrdinaryQualification.write("ocean-counts.json",AdmissionOceanTrace.snapshot());NativeOrdinaryQualification.write("quota.json",AdmissionWorkTrace.intervals());server.saveEverything(false,true,true);Files.writeString(Path.of("result.txt"),"PASS");}catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("NATIVE_ORDINARY_ADMISSION_FAIL",t);try{Files.writeString(Path.of("result.txt"),"FAIL "+t);}catch(Exception ignored){}}finally{server.halt(false);}});}
}
